import type { PropsWithChildren } from 'react';
import React from 'react';
import { isElement } from 'react-is';

import { Text } from '../../typography/Text.js';

export type TimeframeSelectorDisplayValueProps = PropsWithChildren<unknown>;

/**
 * Typeguard function that will check if a React.Node is a TimeframeSelector.DisplayValue
 * @internal
 */
export function _isTimeframeSelectorDisplayValueElement(
  child: React.ReactNode,
): child is React.ReactElement<TimeframeSelectorDisplayValueProps> {
  return isElement(child) && child.type === DisplayValue;
}

/**
 * `TimeframeSelector.DisplayValue` defines a custom display value within the Trigger. A TimeframeSelector.DisplayValue component
 * is only valid within a TimeframeSelector.Trigger.
 */
export const DisplayValue = (props: TimeframeSelectorDisplayValueProps) => {
  const { children } = props;

  if (!children) {
    return null;
  }

  return isElement(children) ? children : <Text as="p">{children}</Text>;
};

DisplayValue.displayName = 'TimeframeSelector.DisplayValue';
